    // ==================== TAB NAVIGATION ====================
    function switchTab(tabId) {
      document.querySelectorAll(".tab-panel").forEach(p => p.classList.add("hidden"));
      const target = document.getElementById(`tab-panel-${tabId}`);
      if (target) target.classList.remove("hidden");

      document.querySelectorAll(".nav-tab-btn").forEach(btn => {
        const t = btn.getAttribute("data-tab");
        btn.setAttribute("aria-current", t === tabId ? "page" : "false");
        if (t === tabId) {
          btn.className = "nav-tab-btn px-3 py-2 rounded-xl text-xs sm:text-sm font-semibold whitespace-nowrap transition bg-sage-600 text-white shadow-sm";
        } else if (t === "workspace") {
          btn.className = "nav-tab-btn px-3 py-2 rounded-xl text-xs sm:text-sm font-semibold whitespace-nowrap transition text-emerald-800 bg-emerald-50 hover:bg-emerald-100 border border-emerald-300";
        } else if (t === "addons") {
          btn.className = "nav-tab-btn px-3 py-2 rounded-xl text-xs sm:text-sm font-semibold whitespace-nowrap transition text-amber-900 bg-amber-50 hover:bg-amber-100 border border-amber-300";
        } else {
          btn.className = "nav-tab-btn px-3 py-2 rounded-xl text-xs sm:text-sm font-semibold whitespace-nowrap transition text-gray-700 hover:bg-cream";
        }
      });
    }

    // ==================== CLIPBOARD & CSV EXPORT HELPERS ====================
    function copyTextToClipboard(text, successMsg) {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(() => {
          showToast(successMsg);
        }).catch(() => fallbackCopy(text, successMsg));
      } else {
        fallbackCopy(text, successMsg);
      }
    }

    function fallbackCopy(text, successMsg) {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.left = "-9999px";
      document.body.appendChild(ta);
      ta.select();
      try {
        if (!document.execCommand("copy")) throw new Error("Copy failed");
        showToast(successMsg);
      } catch (e) {
        showToast("Could not auto-copy; please select and copy manually.", "error");
      }
      ta.remove();
    }

    function downloadCSV(filename, rows) {
      const csvContent = rows.map(r => r.map(cell => {
        const s = Hub.csvCell(cell).replace(/"/g, '""');
        return `"${s}"`;
      }).join(",")).join("\n");
      const blob = new Blob(["\uFEFF", csvContent], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      showToast(`Exported ${filename} — ready for Google Sheets!`);
    }

